SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;


UPDATE t_opportunity SET converted_project_id = 5001 + ((id - 14501) % 100), converted_quotation_id = 15001 + ((id - 14501) % 60) WHERE id IN (14551,14552,14553,14554,14555);

UPDATE t_project SET source_opportunity_id = 14501 + ((id - 5001) % 60) WHERE id % 7 = 0;

UPDATE t_quotation SET source_opportunity_id = 14501 + ((id - 15001) % 60) WHERE id % 5 = 0;

UPDATE t_proposal SET source_opportunity_id = 14501 + ((id - 6001) % 60) WHERE id % 6 = 0;

SET FOREIGN_KEY_CHECKS = 1;
